def read_header(path):
    with open(path,"rb") as f:
        n=struct.unpack("<Q", f.read(8))[0]
        h=f.read(n)
        j=json.loads(h)
        # data start = 8+n
        fsize=os.path.getsize(path)
        return j, n, fsize

